<?php
require __DIR__.'/ui.php';role(['admin','gerente']);$p=db();if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();$p->prepare("INSERT INTO delivery_zones(neighborhood,fee,min_order,active)VALUES(?,?,?,1) ON CONFLICT(neighborhood) DO UPDATE SET fee=excluded.fee,min_order=excluded.min_order,active=1")->execute([trim($_POST['neighborhood']),$_POST['fee'],$_POST['min_order']]);go('delivery-zones.php');}$rows=$p->query("SELECT * FROM delivery_zones ORDER BY neighborhood")->fetchAll();page_head('Taxas de entrega por bairro');?>
<div class="grid g2"><div class="card"><h2>Novo bairro</h2><form method="post"><?=csrf_field()?><label>Bairro</label><input name="neighborhood" required><label>Taxa de entrega</label><input type="number" step=".01" name="fee" value="0"><label>Pedido mínimo</label><input type="number" step=".01" name="min_order" value="0"><button class="primary">Salvar</button></form></div><div class="card"><h2>Bairros</h2><div class="table"><table><tr><th>Bairro</th><th>Taxa</th><th>Mínimo</th></tr><?php foreach($rows as $r):?><tr><td><?=e($r['neighborhood'])?></td><td><?=money($r['fee'])?></td><td><?=money($r['min_order'])?></td></tr><?php endforeach;?></table></div></div></div><?php page_foot();?>